import React from "react";

export default function VideoProgressBar({ videoProgress, videoActive }) {
  if (!videoActive || !videoProgress) return null;

  const { percent, filename } = videoProgress;
  const done = percent >= 100;

  return (
    <div style={{
      background: "#1a1d27", borderRadius: 10,
      border: `1px solid ${done ? "#22c55e" : "#3b5bdb"}`,
      padding: "12px 16px", marginBottom: 16,
      display: "flex", alignItems: "center", gap: 14,
    }}>
      <div style={{ flex: 1 }}>
        <div style={{ display: "flex", justifyContent: "space-between",
                      fontSize: 12, color: "#9ca3af", marginBottom: 6 }}>
          <span>
            {done ? "Processing complete" : "Processing video"} —{" "}
            <strong style={{ color: "#e8e6df" }}>{filename}</strong>
          </span>
          <span style={{ fontWeight: 600, color: done ? "#22c55e" : "#3b5bdb" }}>
            {percent}%
          </span>
        </div>
        <div style={{ height: 5, background: "#2a2d3a", borderRadius: 3, overflow: "hidden" }}>
          <div style={{
            width: `${percent}%`, height: "100%", borderRadius: 3,
            background: done ? "#22c55e" : "#3b5bdb",
            transition: "width .4s ease, background .3s",
          }} />
        </div>
      </div>
      {!done && (
        <div style={{
          width: 16, height: 16, borderRadius: "50%",
          border: "2px solid #2a2d3a", borderTopColor: "#3b5bdb",
          flexShrink: 0, animation: "spin .7s linear infinite",
        }}>
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
      )}
    </div>
  );
}
